from collections import deque
def fill_enclosed(g, wall, newcol):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in g]
    q=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]!=wall: q.append((i,j)); seen[i][j]=True
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]!=wall and not seen[i][j]: q.append((i,j)); seen[i][j]=True
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            a,b=i+di,j+dj
            if 0<=a<h and 0<=b<w and not seen[a][b] and g[a][b]!=wall:
                seen[a][b]=True; q.append((a,b))
    return [[newcol if not seen[i][j] and g[i][j]!=wall else g[i][j] for j in range(w)] for i in range(h)]

